import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  LayoutGrid, List, Search, Plus, Star, Home
} from 'lucide-react';
import { DashboardHeader } from '../components/dashboard/DashboardHeader';
import { Button } from '../components/ui/button';
import { Badge } from '../components/ui/badge';
import { Card } from '../components/ui/card';
import { CreateProjectModal } from '../components/modals/CreateProjectModal';
import { ImprovedProjectCard } from '../components/shared/ImprovedProjectCard';
import { projectService } from '../services/projectService';
import { useAuth } from '../contexts/AuthContext';
import { formatDate } from '../utils/formatters';
import Swal from 'sweetalert2';

const ProjectsPage = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [view, setView] = useState('grid');
  const [showCreateModal, setShowCreateModal] = useState(false);

  useEffect(() => {
    loadProjects();
  }, []);

  const loadProjects = async () => {
    try {
      setLoading(true);
      const data = await projectService.getAll();
      setProjects(data);
    } catch (error) {
      Swal.fire({
        icon: 'error',
        title: 'Error al Cargar Proyectos',
        text: error.response?.data?.detail || 'No se pudieron cargar los proyectos. Por favor, intenta de nuevo.',
        confirmButtonColor: '#dc2626',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleToggleFavorite = async (projectId, isFavorite) => {
    try {
      await projectService.update(projectId, { is_favorite: isFavorite });
      setProjects(prev => prev.map(p => 
        p._id === projectId ? { ...p, is_favorite: isFavorite } : p
      ));
      
      Swal.fire({
        icon: 'success',
        title: isFavorite ? '⭐ Agregado a favoritos' : 'Quitado de favoritos',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 2000,
        timerProgressBar: true,
      });
    } catch (error) {
      console.error('Error toggling favorite:', error);
    }
  };

  const handleEdit = (project) => {
    Swal.fire({
      title: 'Editar Proyecto',
      text: `Función de edición para: ${project.project_name}`,
      icon: 'info',
      confirmButtonColor: '#16a34a',
    });
  };

  const handleDelete = async (project) => {
    const result = await Swal.fire({
      title: '¿Eliminar Proyecto?',
      html: `Se eliminará <strong>${project.project_name}</strong> y todas sus tareas.<br><br>Esta acción no se puede deshacer.`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      cancelButtonColor: '#6b7280',
      confirmButtonText: 'Sí, eliminar',
      cancelButtonText: 'Cancelar',
    });

    if (result.isConfirmed) {
      try {
        await projectService.delete(project._id);
        setProjects(prev => prev.filter(p => p._id !== project._id));
        
        Swal.fire({
          icon: 'success',
          title: 'Proyecto Eliminado',
          toast: true,
          position: 'top-end',
          showConfirmButton: false,
          timer: 2000,
        });
      } catch (error) {
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'No se pudo eliminar el proyecto',
          confirmButtonColor: '#dc2626',
        });
      }
    }
  };

  const handleDuplicate = async (project) => {
    const result = await Swal.fire({
      title: 'Duplicar Proyecto',
      text: `¿Crear una copia de "${project.project_name}"?`,
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#16a34a',
      cancelButtonColor: '#6b7280',
      confirmButtonText: 'Sí, duplicar',
      cancelButtonText: 'Cancelar',
    });

    if (result.isConfirmed) {
      try {
        const newProject = {
          ...project,
          project_name: `${project.project_name} (Copia)`,
          status: 'planning',
          is_favorite: false,
          tasks: [],
        };
        delete newProject._id;
        delete newProject.created_at;
        delete newProject.updated_at;
        delete newProject.client_id;
        
        // Mantener solo el ID del cliente
        newProject.client_id = project.client_id?._id || project.client_id;

        const created = await projectService.create(newProject);
        setProjects(prev => [created, ...prev]);
        
        Swal.fire({
          icon: 'success',
          title: 'Proyecto Duplicado',
          toast: true,
          position: 'top-end',
          showConfirmButton: false,
          timer: 2000,
        });
      } catch (error) {
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'No se pudo duplicar el proyecto',
          confirmButtonColor: '#dc2626',
        });
      }
    }
  };

  const handlePause = async (project) => {
    const newStatus = project.status === 'on_hold' ? 'in_progress' : 'on_hold';
    
    try {
      await projectService.update(project._id, { status: newStatus });
      setProjects(prev => prev.map(p => 
        p._id === project._id ? { ...p, status: newStatus } : p
      ));
      
      Swal.fire({
        icon: 'success',
        title: newStatus === 'on_hold' ? '⏸️ Proyecto Pausado' : '▶️ Proyecto Reanudado',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 2000,
      });
    } catch (error) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'No se pudo cambiar el estado',
        confirmButtonColor: '#dc2626',
      });
    }
  };

  const handleArchive = (project) => {
    Swal.fire({
      title: 'Archivar Proyecto',
      text: 'Función de archivado - Por implementar',
      icon: 'info',
      confirmButtonColor: '#16a34a',
    });
  };

  const handleProjectClick = (project) => {
    navigate(`/projects/${project._id}`);
  };

  const calculateProgress = (project) => {
    if (!project.tasks || project.tasks.length === 0) return 0;
    const completed = project.tasks.filter(t => t.status === 'completed').length;
    return Math.round((completed / project.tasks.length) * 100);
  };

  const getStatusColor = (status) => {
    const colors = {
      planning: 'bg-yellow-100 text-yellow-700 border-yellow-200',
      in_progress: 'bg-blue-100 text-blue-700 border-blue-200',
      completed: 'bg-green-100 text-green-700 border-green-200',
      cancelled: 'bg-red-100 text-red-700 border-red-200',
      on_hold: 'bg-gray-100 text-gray-700 border-gray-200'
    };
    return colors[status] || colors.planning;
  };

  const getStatusLabel = (status) => {
    const labels = {
      planning: 'Planificación',
      in_progress: 'En Progreso',
      completed: 'Completado',
      cancelled: 'Cancelado',
      on_hold: 'En Pausa'
    };
    return labels[status] || status;
  };

  const filteredProjects = projects.filter(p => {
    const matchesFilter = 
      filter === 'all' || 
      (filter === 'active' && p.status === 'in_progress') ||
      (filter === 'completed' && p.status === 'completed') ||
      (filter === 'favorites' && p.is_favorite);
    
    const matchesSearch = 
      p.project_name.toLowerCase().includes(search.toLowerCase()) ||
      p.client_id?.company_name?.toLowerCase().includes(search.toLowerCase());
    
    return matchesFilter && matchesSearch;
  });

  const favoriteCount = projects.filter(p => p.is_favorite).length;

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50">
        <DashboardHeader />
        <div className="flex items-center justify-center h-96">
          <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-green-500"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <DashboardHeader />

      {/* Header - STICKY */}
      <div className="bg-white border-b sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-4">
              {/* Botón al Dashboard */}
              <Button
                onClick={() => navigate('/dashboard')}
                variant="ghost"
                size="sm"
              >
                <Home className="w-4 h-4 mr-2" />
                Dashboard
              </Button>
              <div>
                <h1 className="text-2xl font-bold text-gray-900">Proyectos</h1>
                <p className="text-sm text-gray-600 mt-1">
                  Gestiona tus proyectos de manera eficiente
                </p>
              </div>
            </div>
            
            {(user?.role === 'super_admin' || user?.role === 'admin' || user?.role === 'user') && (
              <Button
                onClick={() => setShowCreateModal(true)}
                className="bg-green-600 hover:bg-green-700"
              >
                <Plus className="w-4 h-4 mr-2" />
                Nuevo Proyecto
              </Button>
            )}
          </div>

          {/* Filtros y búsqueda */}
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
            <div className="flex-1 relative w-full">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="Buscar proyectos..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent"
              />
            </div>

            <div className="flex flex-wrap gap-2">
              <Button
                onClick={() => setFilter('all')}
                variant={filter === 'all' ? 'default' : 'outline'}
                size="sm"
              >
                Todos ({projects.length})
              </Button>
              <Button
                onClick={() => setFilter('active')}
                variant={filter === 'active' ? 'default' : 'outline'}
                size="sm"
              >
                Activos ({projects.filter(p => p.status === 'in_progress').length})
              </Button>
              <Button
                onClick={() => setFilter('completed')}
                variant={filter === 'completed' ? 'default' : 'outline'}
                size="sm"
              >
                Completados ({projects.filter(p => p.status === 'completed').length})
              </Button>
              <Button
                onClick={() => setFilter('favorites')}
                variant={filter === 'favorites' ? 'default' : 'outline'}
                size="sm"
              >
                <Star className="w-4 h-4 mr-1" />
                Favoritos ({favoriteCount})
              </Button>
            </div>

            <div className="flex border rounded-lg overflow-hidden">
              <button
                onClick={() => setView('grid')}
                className={`p-2 ${view === 'grid' ? 'bg-green-100 text-green-700' : 'bg-white text-gray-700'}`}
              >
                <LayoutGrid className="w-4 h-4" />
              </button>
              <button
                onClick={() => setView('list')}
                className={`p-2 ${view === 'list' ? 'bg-green-100 text-green-700' : 'bg-white text-gray-700'}`}
              >
                <List className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Projects Grid/List */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {view === 'grid' ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredProjects.map(project => (
              <ImprovedProjectCard
                key={project._id}
                project={project}
                onToggleFavorite={handleToggleFavorite}
                onEdit={handleEdit}
                onDelete={handleDelete}
                onDuplicate={handleDuplicate}
                onPause={handlePause}
                onArchive={handleArchive}
                onClick={handleProjectClick}
              />
            ))}
          </div>
        ) : (
          <Card>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="border-b bg-gray-50">
                  <tr className="text-left">
                    <th className="px-6 py-4 text-sm font-semibold text-gray-700">Proyecto</th>
                    <th className="px-6 py-4 text-sm font-semibold text-gray-700">Cliente</th>
                    <th className="px-6 py-4 text-sm font-semibold text-gray-700">Estado</th>
                    <th className="px-6 py-4 text-sm font-semibold text-gray-700">Progreso</th>
                    <th className="px-6 py-4 text-sm font-semibold text-gray-700">Tareas</th>
                    <th className="px-6 py-4 text-sm font-semibold text-gray-700">Vencimiento</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredProjects.map(project => {
                    const progress = calculateProgress(project);
                    const completedTasks = project.tasks?.filter(t => t.status === 'completed').length || 0;
                    const totalTasks = project.tasks?.length || 0;

                    return (
                      <tr
                        key={project._id}
                        onClick={() => handleProjectClick(project)}
                        className="border-b hover:bg-gray-50 cursor-pointer"
                      >
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-2">
                            {project.is_favorite && (
                              <Star className="w-4 h-4 fill-yellow-400 text-yellow-400" />
                            )}
                            <span className="font-semibold text-gray-900">
                              {project.project_name}
                            </span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-gray-600">
                          {project.client_id?.company_name}
                        </td>
                        <td className="px-6 py-4">
                          <Badge className={`border ${getStatusColor(project.status)}`}>
                            {getStatusLabel(project.status)}
                          </Badge>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-2">
                            <div className="w-24 bg-gray-200 rounded-full h-2">
                              <div
                                className="bg-green-500 h-2 rounded-full"
                                style={{ width: `${progress}%` }}
                              ></div>
                            </div>
                            <span className="text-sm font-semibold text-gray-700">
                              {progress}%
                            </span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-gray-600">
                          {completedTasks}/{totalTasks}
                        </td>
                        <td className="px-6 py-4 text-gray-600 text-sm">
                          {formatDate(project.estimated_end_date)}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        )}

        {filteredProjects.length === 0 && (
          <div className="text-center py-12 bg-white rounded-xl">
            <div className="inline-block bg-gray-100 p-6 rounded-full mb-4">
              <LayoutGrid className="w-12 h-12 text-gray-400" />
            </div>
            <p className="text-gray-600 text-lg mb-2">No se encontraron proyectos</p>
            <p className="text-gray-500 text-sm mb-4">
              {search ? 'Intenta con otros términos de búsqueda' : 'Comienza creando tu primer proyecto'}
            </p>
            {(user?.role === 'super_admin' || user?.role === 'admin' || user?.role === 'user') && (
              <Button
                onClick={() => setShowCreateModal(true)}
                className="bg-green-600 hover:bg-green-700"
              >
                <Plus className="w-4 h-4 mr-2" />
                Crear Proyecto
              </Button>
            )}
          </div>
        )}
      </div>

      {/* Create Project Modal */}
      <CreateProjectModal
        isOpen={showCreateModal}
        onClose={() => setShowCreateModal(false)}
        onSuccess={() => {
          loadProjects();
          setShowCreateModal(false);
        }}
      />
    </div>
  );
};

export default ProjectsPage;
